export type CommunityType = 'City' | 'Neighborhood'

export type CommunityVideoData = {
  /** YouTube video ID (the `v=` param). */
  id: string
  title: string
  /** Runtime in seconds — used for the badge and the VideoObject schema. */
  durationSeconds: number
  /** ISO date, e.g. '2025-12-18'. Required by Google for VideoObject. */
  uploadDate: string
  description: string
}

export interface CommunityItem {
  slug: string
  name: string
  type: CommunityType
  region: string
  description: string
  // Optional SEO overrides — used when the generic "{name} Real Estate" title/description
  // isn't earning clicks for a page's actual ranking queries (see Search Console data).
  metaTitle?: string
  metaDescription?: string
  overview: string
  quickFacts: Array<{ label: string; value: string }>
  linkedNeighborhoods?: string[]
  priceRanges?: Array<{ type: string; range: string; minPrice?: number; maxPrice?: number; amenities?: string[]; propertyTypes?: string[] }>
  hasMembershipCommunities?: boolean
  highlights?: string[]
  photos?: string[]
  photoCredits?: string[]  // parallel to photos — e.g. 'Photo by Jane Doe / Unsplash'
  /** Our own YouTube tour for this community, rendered as a click-to-load facade. */
  video?: CommunityVideoData
  // Curated saved-search buttons (real saved URLs from search.doyouneedahome.com — never auto-generated)
  savedSearches?: Array<{ label: string; sublabel?: string; url: string }>

  // Extended content fields
  lifestyle?: string
  localLoves?: string[]
  schoolOverview?: string
  schoolList?: Array<{ category: string; schools: Array<{ name: string; url?: string }> }>
  hospitals?: Array<{ name: string; url: string; note?: string }>
  commuteTimes?: Array<{ destination: string; time: string }>
  dining?: string[]
  outdoorActivities?: string[]
  hiddenGems?: string[]
  popularNeighborhoods?: string[]
  subNeighborhoods?: Array<{ name: string; description: string }>
  keyLinks?: Array<{ label: string; url: string; category: string }>
  // Cross-domain hand-off module (e.g. WPB → CondoWPB.com) — rendered as its own section
  sisterSite?: {
    eyebrow: string
    heading: string
    intro: string
    links: Array<{ label: string; sublabel?: string; url: string }>
  }
  searchCity?: string
  /**
   * The name Ylopo files this place under, when it differs from ours. Their
   * location index is the MLS's, not the marketing name — Panther National is
   * "Panther National At Avenir Pod" over there. Only set this when the
   * autocomplete disagrees with `name`; check with:
   *   portal.ylopo.com/api/1.0/autocomplete?q=<name>&partyWebsite=search.doyouneedahome.com
   */
  ylopoLocation?: string
  lat?: number
  lng?: number
  // Slugs of similar-priced communities within the same PUD/master-planned community
  similarNeighborhoods?: string[]
}

